from pathlib import Path
import json,hashlib,html
r=Path('docs/homepage-refinement/phase-11b');e=r/'evidence';before=json.loads((e/'before-review.json').read_text());after=json.loads((e/'after-review.json').read_text());contrast=json.loads((e/'contrast.json').read_text());axe={p:json.loads((e/f'{p}-axe.json').read_text()) for p in ['before','after']}
assert len(before)==len(after)==7
assert all(x['contentHash']==y['contentHash'] for x,y in zip(before,after))
assert all(t['minimumSampledContrast'] >= (3 if i in [1,2] else 4.5) for row in contrast for i,t in enumerate(row['text']))
assert all(not x['violations'] for x in axe['after'])
initial=json.loads((e/'before-hashes.json').read_text());changed=[p for p,h in initial.items() if not Path(p).exists() or hashlib.sha256(Path(p).read_bytes()).hexdigest()!=h];allowed={
'src/components/sections/quotation/quotation.css','src/components/sections/quotation/quotation-draft.tsx','src/components/sections/industry-experience/industries.css','src/components/sections/company-introduction/introduction.css','src/components/sections/corporate-purpose/purpose.css','src/components/sections/hero/hero.css','tests/quotation.test.ts','tests/e2e/introduction.spec.ts','tests/e2e/photography.spec.ts'}
assert not set(changed)-allowed
scope={'changedExistingFiles':changed,'unexpectedChanges':list(set(changed)-allowed),'allPublicAssetsUnchanged':all(hashlib.sha256(Path(p).read_bytes()).hexdigest()==h for p,h in initial.items() if p.startswith('public/')),'mediaContentTokensNavigationRoutesTransportAndMotionPreserved':all(hashlib.sha256(Path(p).read_bytes()).hexdigest()==h for p,h in initial.items() if p.startswith(('src/config/','src/content/','src/design-system/','src/hooks/','src/lib/','src/app/','src/components/layout/'))),'allDefaultContentHashesMatch':True,'draftBodiesMatch':all(x.get('draft',{}).get('summary')==y.get('draft',{}).get('summary') for x,y in zip(before,after))}
(e/'scope-integrity.json').write_text(json.dumps(scope,indent=2)+'\n')
checks='Fresh baseline: lint, strict TypeScript, production build, **44 unit tests and 132 Playwright tests passed**. Refined build: lint, strict TypeScript, production build, **45 unit tests and 140 full-suite Playwright tests passed**; **8 targeted tests passed again** after adding explicit enlarged-error containment checks. No tests skipped. Exact logs are under evidence/.\n\n'
limits='Chromium desktop and iPhone-emulated Chromium are not physical Safari/iOS, Firefox, VoiceOver or NVDA validation. 200% root text, narrow CSS viewports and CDP 2× visual magnification are tested separately; native browser-chrome zoom and spoken announcements remain unverified. Axe results and sampled contrast are not a complete WCAG certification. No production field performance or final-font composition claim.\n\n'
conditions='**CONDITIONAL GO for Phase 11C**, subject to review of Phase 11B and explicit approval of the next scope. **Not public-launch approval.** Remaining gates include licensed complete Noto Serif WOFF2 delivery, vector/alternate logo masters, four held photographic placements, real assistive-technology/native zoom and cross-browser validation, final performance testing, official contact/address confirmation, inner-page readiness and deliberate launch/indexing decisions. Existing noindex remains intact. No Phase 11C work or deployment occurred.\n\n'
rows=[
('AUD-06','Wrapped labels displaced paired controls by 22.4px at 1024px.','quotation/quotation.css','Available-width auto-fit tracks: minmax(min(100%,18rem),1fr); wide fields span the grid. Two columns only when the form can support labels, single column otherwise; no fixed label heights.','quotation-1024','Label/input bindings, order, errors, autocomplete, keyboard flow and validation preserved. The taller 1024px form is an intentional reading tradeoff.','Low–medium: grid thresholds at enlarged text. Seven widths at 100/200%, including invalid errors, passed.'),
('AUD-05','Decorative ochre numerals were faint on light surfaces; axe flagged six at narrow widths and one at desktop.','industry-experience/industries.css; corporate-purpose/purpose.css','Navy numerals on light surfaces; amber retained on the navy manufacturing panel and existing accent rules. aria-hidden remains unchanged.','industries-390','These are decorative, not essential body text; headings already convey meaning. The change improves hierarchy, not a claim that decorative text automatically violates essential-text criteria.','Low: paint only. Nine aria-hidden numerals and surface-specific colours checked.'),
('AUD-12','Generic draft div carried aria-labelledby without a grouping role; axe marked it incomplete.','quotation/quotation-draft.tsx','Add role="group" to the existing wrapper and keep its existing H4 label. No extra landmark, focus target or live wrapper.','draft-1024','One existing status and one copy-status live area remain. Preparation focus, copy/select, short mailto and long-enquiry fallback preserved.','Low: accessibility tree. Unit/keyboard/copy/axe checks pass; actual spoken output still needs AT testing.'),
('AUD-07','The 768px Introduction image was 691px tall, with repeated large panel spacing through Industries. Editorial concern, not a functional defect.','company-introduction/introduction.css; industry-experience/industries.css','Below 64rem: Introduction 4:3 detail frame, 2rem grid gap and 2.5–3.5rem padding. Industry photos remain 4:3; panel gaps and numeral/context spacing tighten modestly. Desktop composition unchanged.','introduction-768','All text, four sector descriptions, existing quotation shortcuts, images/captions and DOM order retained. No carousel, hidden content or smaller type.','Medium: crop and reflow. Actual mobile/tablet photographs reviewed and image/fallback aspect-ratio tests updated.'),
('AUD-16','Adjacent navy Advantage/Vision sections had a faint boundary.','corporate-purpose/purpose.css','Use a 2px existing-amber boundary on Vision in place of the faint paper-mix line. Keep both navy surfaces and existing eyebrow/heading hierarchy.','advantage-vision-1440','CSS decoration adds no semantic noise or animation. Existing named sections convey the transition.','Low: static one-pixel height difference. Section adjacency and colour checked.'),
('Hero finish','At 390px machinery was almost lost in the combined horizontal and vertical overlay; credit tracking was dense.','hero/hero.css','Only below 40rem: horizontal navy alpha 88→62%; vertical navy 92% at base, 70% at 12%, transparent at 45%; credit tracking .025em. Source/crops/layout unchanged.','hero-390','Credit and illustrative/non-site statement retained at 12px; footer remains in normal flow. White/supporting text and large amber headline checked against actual backgrounds.','Medium: contrast. Seven-width samples pass; credit/scroll do not overlap. Desktop 1440px hero screenshot is pixel-identical to baseline.')]
header='Updated **18 November 2026 (Africa/Harare)**. Phase 11B only.\n\n'
def write(name,text):(r/name).write_text(text)
implementation='# Phase 11B implementation\n\n'+header+'## Mandatory review and baseline\n\nAll nine required reports were present at the exact requested paths; no missing-file discrepancy. Read DESIGN, ARCHITECTURE, CONTENT, IMPLEMENTATION, Phase 10 executive/backlog/readiness, Phase 11A QA and final Phase 11A.5 readiness. Historical statements were interpreted against the current R1/seven-photo configuration. Inspected header/navigation, all homepage sections, quote fields/draft, footer, tokens/type and scoped GSAP/Motion/reduced-motion foundations. Current screenshots and source were reviewed before editing; the fresh baseline is recorded independently of Git because prior work is uncommitted.\n\n'+checks+'## Changes\n\n'
for id,problem,files,solution,image,aria,risk in rows:implementation+=f'### {id}\n\n- Original: {problem}\n- Production files under src/components/sections/: `{files}`.\n- Solution: {solution}\n- Evidence: [before](screenshots/before/{image}.png), [after](screenshots/after/{image}.png).\n- Accessibility: {aria}\n- Regression risk/results: {risk}\n\n'
implementation+='## Test and documentation files\n\nAdded tests/e2e/phase-11b.spec.ts (four cases in both projects). Added the draft-group unit assertion in tests/quotation.test.ts. Updated existing Introduction/photo fallback frame assertions to expect 4:3 below 1024px and 5:6 at/above it. Existing assertions were adapted to the intended responsive frame, not removed. Updated DESIGN/ARCHITECTURE/IMPLEMENTATION only to reflect current boundaries; all seven requested phase reports, 32 screenshots, review board and raw evidence are here. No production dependency or package/lockfile change.\n\n## Protected scope\n\nAll public files, media configs, content, tokens/type, hooks, schema/transport, App Router/indexing and navigation/footer source hashes match the pre-change snapshot. Main text hashes match at all seven widths; generated draft bodies match before/after. Source-only edits are six existing section files; no new production component or JavaScript interaction. See evidence/scope-integrity.json.\n\n'+limits+conditions
write('IMPLEMENTATION.md',implementation)
visual='# Visual refinement report\n\n'+header+'[Before/after review board](REVIEW_BOARD.html) · [comparison notes](BEFORE_AFTER_REVIEW.md)\n\n'
for id,problem,files,solution,image,aria,risk in rows:visual+=f'## {id}\n\n{problem} {solution}\n\n[Before](screenshots/before/{image}.png) · [After](screenshots/after/{image}.png). {aria} Risk/result: {risk}\n\n'
visual+='## Cross-section consistency decision\n\nShared containers, headings, buttons, source imagery/caption alignment and desktop rhythm already form a coherent system. No extra changes were made to Header, Solutions, Advantage accordion, Mission/Values layout, quotation transport or Footer. The only boundary treatment is the documented Advantage/Vision rule. No gradients outside the existing hero overlay, cards, new palette, new typography system or animation were introduced. Desktop page height changes by one pixel solely because the boundary changes from 1px to 2px.\n\nThe actual after screenshots were opened for inspection: the casting detail remains legible in the shorter tablet frame, the form labels/controls now stack evenly at 1024px, the mobile excavator edge is more visible, its credit remains readable and the amber rule identifies the new editorial movement. These are evidence-linked judgments, not a design score or user-research claim.\n\n'+checks
write('VISUAL_REFINEMENT_REPORT.md',visual)
responsive='# Responsive report\n\n'+header+'## Fresh measurements\n\nAll required widths tested at default and 200% root text. Default CSS viewport measurements below use reduced motion, DPR1, decoded images and the same 900px height before/after. Heights are descriptive; a shorter page was not the sole objective.\n\n| Width | Before page px | After page px | Delta px | Intro image before→after px | Form after |\n|---|---:|---:|---:|---|---|\n'
for a,b in zip(before,after):
 f={v['id']:v for v in b['fields']};mode='single column' if abs(f['quotation-company']['control']['x']-f['quotation-telephone']['control']['x'])<1 else 'paired/aligned';responsive+=f"| {a['width']} | {a['pageHeight']} | {b['pageHeight']} | {b['pageHeight']-a['pageHeight']:+} | {a['introFrame']['height']:.0f}→{b['introFrame']['height']:.0f} | {mode} |\n"
responsive+='\nAt 1024px the form becomes taller instead of forcing misaligned pairs; that is deliberate. At 768px the full-width form can still support two columns, while the Introduction/Industries rhythm improves. At desktop, photography frames, containers and pacing stay intact. Hero height and credit height match the baseline at all seven widths. No mobile/tablet description or image was hidden, and no reading font or touch target was reduced.\n\n## Verification\n\nNo document horizontal overflow at 320/375/390/768/1024/1440/1920px. Eight field bindings/order stay unchanged. Paired controls align; stacked controls follow reading order. Labels, required/optional markers, hints and invalid errors remain unclipped, including 200% text. Existing Phase 11A discovery focus/history, menu/dialog behavior, form anchors and quotation shortcuts pass. Existing CDP 2× magnification is a separate pinch-style test, not native browser-chrome zoom.\n\n'+limits
write('RESPONSIVE_REPORT.md',responsive)
access='# Accessibility report\n\n'+header+'## Semantics and functional preservation\n\nAUD-12 now uses a named group for the coherent prepared summary/actions. The wrapper itself is not live or focusable; its existing H4, ready status, copy status and Select summary behavior remain. No duplicate ready announcement or new landmark. Draft source/body and mailto/copy architecture are unchanged. Keyboard preparation keeps focus on Prepare; Select summary focuses/selects the readonly text; edit invalidation, validation and long-enquiry manual fallback continue passing.\n\nAUD-06 uses text-relative available-width reflow rather than fixed label heights. Errors/descriptions/field names are unchanged. AUD-05 preserves aria-hidden decorative numerals and strengthens paint on light surfaces; essential headings already carry their meaning. Decorative exemptions are explicitly recognized rather than presenting the original numeral findings as proven essential-body-text violations.\n\n## Axe checks\n\nThe already-installed axe-core engine was reused; no dependency added. Scans use WCAG 2 A/AA, 2.1 A/AA and best-practice tags at 390/1024/1440 in default and prepared-draft states.\n\n| Width | State | Before violations (nodes) | After violations | Before generic-label incomplete | After generic-label incomplete |\n|---|---|---:|---:|---:|---:|\n'
for a,b in zip(axe['before'],axe['after']):access+=f"| {a['width']} | {a['state']} | {sum(len(v['nodes']) for v in a['violations'])} | {sum(len(v['nodes']) for v in b['violations'])} | {sum(len(v['nodes']) for v in a['incomplete'] if v['id']=='aria-prohibited-attr')} | {sum(len(v['nodes']) for v in b['incomplete'] if v['id']=='aria-prohibited-attr')} |\n"
access+='\nBefore violations were decorative-number contrast findings. After scans report zero violations and no aria-prohibited-attr incompletes in the tested states. Gradient contrast still produces axe incompletes (seven default hero areas; additional native/draft control uncertainties in ready states). These are not silently counted as passes. Hero areas were separately sampled below; native control appearance/spoken AT behavior still needs release validation. Raw node targets/results are in evidence/{before,after}-axe.json.\n\n## Manual-background contrast sampling\n\nComputed foreground colors were compared with actual DPR1 screenshot backgrounds, with editorial/footer foreground hidden by opacity without reflow; text-node range rectangles are sampled every 2px after paint. Empty decorative spans are excluded. Secondary-button background is suppressed with the editorial group, making its white-text result a conservative lower bound (its own additional navy layer only darkens the real background). Normal copy/credits use 4.5:1; large serif headlines use 3:1. This is a bounded raster/rectangle check, not full glyph or conformance certification.\n\n| Width | Eyebrow | White headline | Amber headline | Copy | Secondary action | Scroll | Credit |\n|---|---:|---:|---:|---:|---:|---:|---:|\n'
for row in contrast:access+=f"| {row['width']} | "+' | '.join(f"{t['minimumSampledContrast']:.2f}:1" for t in row['text'])+' |\n'
access+='\nAll sampled areas meet their relevant thresholds; minimum large amber ratio is 3.30:1 and supporting-copy minimum is 5.39:1. Existing motion/reduced-motion cleanup and emergency enlarged-word wrapping remain untouched and pass regressions.\n\n'+limits+conditions
write('ACCESSIBILITY_REPORT.md',access)
regression='# Regression report\n\n'+header+checks+'## Commands\n\n`npm run lint`, `npm run typecheck`, `npm run build`, `npm test`, `PLAYWRIGHT_BROWSERS_PATH=/private/tmp/zieve-playwright npm run test:e2e -- --workers=2`. Final full suite 140 passed; targeted phase-11b.spec.ts subsequently passed 8/8 with explicit enlarged invalid-error containment. Production code was unchanged between those runs. Screenshot/axe/contrast scripts and raw JSON/logs are retained under evidence/. Browser binaries and the existing axe engine are environment tooling, not newly installed app dependencies.\n\n## Coverage\n\nNormal/enlarged field alignment; required/email errors; labels and descriptions; draft grouping and status counts; keyboard preparation/copy/select; existing mailto interception and long-copy fallback; no website POST; numeral semantics/color; boundary adjacency; responsive photo frames; image failure recovery; hero credit/scroll non-overlap; reduced-motion preference cleanup; keyboard header/modal/dropdown/focus; solution/industry links, anchors/history, accordion, mission/values, footer/back-to-top and no-JavaScript states.\n\n## Scope integrity\n\nThe before snapshot protects pre-existing uncommitted work, not just Git HEAD. Only six intended existing production files and three existing tests changed, plus the new targeted test file. All public assets, media configs, source content, tokens/type, motion hooks, routes/indexing, navigation and quotation transport are byte-identical to that snapshot. All seven default main-content hashes match; prepared draft bodies match. No packages/manifests, new backend, new section or deployment. `git diff --check` passes.\n\n'+limits
write('REGRESSION_REPORT.md',regression)
review='# Before/after review\n\n'+header+'[Open the paired screenshot board](REVIEW_BOARD.html). The 32 captures comprise matching before/after sets: full homepage at 390/768/1024/1440, hero at 390/1440, form at 768/1024, industry panels and Introduction at 390/768, Advantage/Vision transition at 390/1440, and draft-ready at 390/1024.\n\nAll are actual local production-build screenshots at DPR1 with reduced motion and decoded media. Full-page/hero captures retain the header. Tall section/transition/draft captures hide only sticky header/skip-link paint in the screenshot to avoid obscuring content; production visibility/layout is unchanged. The same capture script and fixture data are used on both sides.\n\n| Change | Before → after evidence | Why the result is preferable |\n|---|---|---|\n'
for id,problem,files,solution,image,aria,risk in rows:review+=f'| {id} | [before](screenshots/before/{image}.png) → [after](screenshots/after/{image}.png) | {solution} |\n'
review+='\n## Measured interpretation\n\n1024px Company/Telephone and Industry/Location controls were displaced by 22.4px; the after form stacks them, preserving complete labels. The 768px intro image is 432px instead of 691px, retaining a clear machining-detail crop with its credit. Whole-page reductions are 340px at 390 and 500px at 768; 1024 grows 319px to accommodate the intentional form reflow. Desktop height grows only 1px for the new boundary. The desktop 1440 hero raw pixels are identical before/after; mobile subject/credit visibility changes are isolated below 40rem. Content/draft hashes match.\n\nThese comparisons support the individual refinements, not a claim that less height alone improves conversion or that user research has validated the journey. No universal visual score or launch approval.\n'
write('BEFORE_AFTER_REVIEW.md',review)
ready='# Phase 11B final readiness\n\n'+header+conditions+'''## Completed scope

- **AUD-06:** quotation grid responds to available width and text size; 1024px labels no longer force uneven input starts. All eight fields, validation, errors, descriptions and transport remain.
- **AUD-05:** decorative numerals use navy on light surfaces and amber on navy. Aria-hidden remains; meaningful headings and accent rules are unchanged.
- **AUD-12:** draft wrapper is an explicitly named group with its existing H4; no new live wrapper, landmark, focus move or transport change.
- **AUD-07:** smaller-screen Introduction detail frame and restrained Introduction/Industries spacing improve text/media balance without removing content, shrinking type or replacing photos.
- **AUD-16:** an existing-amber 2px boundary separates Advantage and Vision while retaining related navy surfaces.
- **Hero finishing:** mobile-only alpha/gradient stops reveal machinery more clearly; credit tracking is refined, with truthful credit preserved, no overlap and passing sampled contrast. Desktop hero is unchanged.
- **Consistency review:** shared containers, headings, actions, photo assets/captions and remaining section compositions are preserved. No broad redesign or extra animation.

## Verification and evidence

'''+checks+'''All seven required widths pass normal/200% reflow and invalid-error containment. Before/after screenshots cover every requested state. Axe reports zero violations in six after states and the generic-label incomplete is resolved; gradient/native-control uncertainties and actual assistive verification are not hidden. Hero sampled minimums: 3.30:1 large amber, 5.39:1 supporting text. All public asset and protected source hashes match; main text and draft summaries match. No new package or production interaction.

[Implementation](IMPLEMENTATION.md) · [Visual report](VISUAL_REFINEMENT_REPORT.md) · [Accessibility](ACCESSIBILITY_REPORT.md) · [Responsive](RESPONSIVE_REPORT.md) · [Regression](REGRESSION_REPORT.md) · [Before/after](BEFORE_AFTER_REVIEW.md) · [Screenshot board](REVIEW_BOARD.html).

## Practical limits and next checkpoint

'''+limits+'''The existing tablet startup header-height observation and earlier brand/release dependencies are not silently declared solved. Phase 11B did not add layout animation or alter header sizing. No final-font/performance or production CWV certification. Review this result before approving any Phase 11C scope. No indexing enabled and nothing deployed.
'''
write('FINAL_READINESS_REPORT.md',ready)
# Local visual review board; never part of the application.
board='<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Phase 11B before/after</title><style>body{margin:0;background:#f5f7f8;color:#0b2233;font:16px/1.6 Georgia,serif}main{max-width:1400px;margin:auto;padding:24px}h1{border-top:3px solid #f2a21a;padding-top:24px}.pair{display:grid;grid-template-columns:1fr 1fr;gap:20px;align-items:start}figure{margin:0}img{width:100%;height:auto;border:1px solid #d5dde2}h2{margin-top:48px}a{color:inherit}@media(max-width:700px){.pair{grid-template-columns:1fr}}</style><main><h1>Phase 11B before / after</h1><p>Actual production-build captures, not a redesign mockup. <a href="BEFORE_AFTER_REVIEW.md">Read the comparison rationale</a>. Baseline and result use identical viewports and fixtures. No deployment.</p>'
for file in sorted((r/'screenshots/before').glob('*.png')):
 board+=f'<section><h2>{html.escape(file.stem)}</h2><div class="pair">'+''.join(f'<figure><figcaption>{phase.title()}</figcaption><a href="screenshots/{phase}/{file.name}"><img loading="lazy" src="screenshots/{phase}/{file.name}" alt="{phase.title()} {html.escape(file.stem)}"></a></figure>' for phase in ['before','after'])+'</div></section>'
write('REVIEW_BOARD.html',board+'</main></html>')
write('screenshots/README.md','# Capture index\n\nSee ../REVIEW_BOARD.html for paired viewing. before/ and after/ each contain 16 actual captures. All use 900px viewport height, DPR1, reduced motion and the same decoded media/fixture data. Full-page and hero retain the header; tall section/transition/draft crops suppress only sticky header/skip-link paint in the screenshot. Production visibility is untouched.\n')
